-- Dynamic Multi-Product Survey Engine (PostgreSQL 14+)
-- Recommended: execute on an empty database; all tables are scoped in survey_engine.
BEGIN;
CREATE SCHEMA IF NOT EXISTS survey_engine;
SET search_path TO survey_engine, public;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TYPE template_status AS ENUM ('draft','published','retired');
CREATE TYPE survey_status AS ENUM ('draft','in_progress','submitted','approved','cancelled');
CREATE TYPE mapping_source AS ENUM ('question','checklist_item');
CREATE TYPE photo_scope AS ENUM ('question','checklist_item');

CREATE TABLE products (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 code text NOT NULL UNIQUE, name text NOT NULL,
 is_active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sections (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 code text NOT NULL UNIQUE, name text NOT NULL,
 is_active boolean NOT NULL DEFAULT true
);
CREATE TABLE questions (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 code text NOT NULL UNIQUE, default_label text NOT NULL,
 default_input_type text NOT NULL CHECK (default_input_type IN ('text','textarea','number','date','boolean','select','radio','multi_select','checklist')),
 is_active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE parameters (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 code text NOT NULL UNIQUE, name text NOT NULL,
 data_type text NOT NULL CHECK (data_type IN ('text','number','boolean','date','json')),
 default_unit text, is_active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now()
);
-- These 3 associations are reusable admin catalog mappings, not historical survey configuration.
CREATE TABLE product_questions (
 product_id bigint NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
 question_id bigint NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,
 is_enabled boolean NOT NULL DEFAULT true,
 PRIMARY KEY (product_id,question_id)
);
CREATE TABLE product_parameters (
 product_id bigint NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
 parameter_id bigint NOT NULL REFERENCES parameters(id) ON DELETE RESTRICT,
 is_enabled boolean NOT NULL DEFAULT true,
 PRIMARY KEY (product_id,parameter_id)
);
CREATE TABLE question_parameters (
 question_id bigint NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,
 parameter_id bigint NOT NULL REFERENCES parameters(id) ON DELETE RESTRICT,
 default_mapping_rule jsonb NOT NULL DEFAULT '{"operator":"direct"}'::jsonb CHECK (jsonb_typeof(default_mapping_rule)='object'),
 PRIMARY KEY (question_id, parameter_id)
);

CREATE TABLE survey_templates (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 code text NOT NULL UNIQUE, name text NOT NULL, description text,
 is_active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE survey_template_versions (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 template_id bigint NOT NULL REFERENCES survey_templates(id) ON DELETE RESTRICT,
 version_no integer NOT NULL CHECK (version_no > 0),
 status template_status NOT NULL DEFAULT 'draft',
 published_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE (template_id,version_no),
 CHECK ((status='draft' AND published_at IS NULL) OR (status IN ('published','retired') AND published_at IS NOT NULL))
);
CREATE TABLE template_products (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 version_id bigint NOT NULL REFERENCES survey_template_versions(id) ON DELETE RESTRICT,
 product_id bigint NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
 UNIQUE (version_id, product_id),
 UNIQUE (id,version_id,product_id)
);
CREATE TABLE template_questions (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 version_id bigint NOT NULL REFERENCES survey_template_versions(id) ON DELETE RESTRICT,
 question_id bigint NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,
 section_id bigint REFERENCES sections(id) ON DELETE RESTRICT,
 section_code_snapshot text, section_label_snapshot text,
 question_no text NOT NULL,
 question_key text NOT NULL,
 label_snapshot text NOT NULL,
 input_type text NOT NULL CHECK (input_type IN ('text','textarea','number','date','boolean','select','radio','multi_select','checklist')),
 unit_snapshot text,
 is_required boolean NOT NULL DEFAULT false,
 is_visible_default boolean NOT NULL DEFAULT true,
 helper_instruction text,
 visibility_rule jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(visibility_rule)='object'),
 validation_rule jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(validation_rule)='object'),
 note_config jsonb NOT NULL DEFAULT '{"enabled":true,"required":false}'::jsonb CHECK (jsonb_typeof(note_config)='object'),
 photo_config jsonb NOT NULL DEFAULT '{"enabled":false,"required":false,"max_files":0}'::jsonb CHECK (jsonb_typeof(photo_config)='object'),
 sort_order integer NOT NULL DEFAULT 0,
 UNIQUE (version_id,question_key),
 UNIQUE (id,version_id)
);
-- A question can appear in many products; settings and mappings can differ per product.
CREATE TABLE template_product_questions (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 template_product_id bigint NOT NULL REFERENCES template_products(id) ON DELETE RESTRICT,
 template_question_id bigint NOT NULL REFERENCES template_questions(id) ON DELETE RESTRICT,
 is_required_override boolean,
 visibility_rule_override jsonb CHECK (visibility_rule_override IS NULL OR jsonb_typeof(visibility_rule_override)='object'),
 UNIQUE (template_product_id, template_question_id),
 UNIQUE (id,template_product_id)
);
CREATE TABLE template_product_parameters (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 template_product_id bigint NOT NULL REFERENCES template_products(id) ON DELETE RESTRICT,
 parameter_id bigint NOT NULL REFERENCES parameters(id) ON DELETE RESTRICT,
 parameter_code_snapshot text NOT NULL,
 parameter_name_snapshot text NOT NULL,
 data_type_snapshot text NOT NULL CHECK (data_type_snapshot IN ('text','number','boolean','date','json')),
 unit_snapshot text,
 is_required boolean NOT NULL DEFAULT false,
 validation_rule jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(validation_rule)='object'),
 UNIQUE (template_product_id,parameter_id),
 UNIQUE (id,template_product_id)
);
CREATE TABLE template_question_options (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 template_question_id bigint NOT NULL REFERENCES template_questions(id) ON DELETE RESTRICT,
 option_key text NOT NULL,
 option_label text NOT NULL,
 option_value jsonb NOT NULL,
 sort_order integer NOT NULL DEFAULT 0,
 UNIQUE (template_question_id,option_key)
);
CREATE TABLE template_checklist_items (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 template_question_id bigint NOT NULL REFERENCES template_questions(id) ON DELETE RESTRICT,
 item_key text NOT NULL, item_label text NOT NULL,
 sort_order integer NOT NULL DEFAULT 0, is_required boolean NOT NULL DEFAULT false,
 condition_options jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(condition_options)='array'),
 has_visibility_field boolean NOT NULL DEFAULT true,
 note_config jsonb NOT NULL DEFAULT '{"enabled":true,"required":false}'::jsonb CHECK (jsonb_typeof(note_config)='object'),
 photo_config jsonb NOT NULL DEFAULT '{"enabled":false,"required":false,"max_files":0}'::jsonb CHECK (jsonb_typeof(photo_config)='object'),
 UNIQUE (template_question_id,item_key),
 UNIQUE (id,template_question_id)
);
-- Snapshot parameter rules: question-level OR checklist-item-level; product scoped.
CREATE TABLE template_parameter_mappings (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 template_product_question_id bigint NOT NULL REFERENCES template_product_questions(id) ON DELETE RESTRICT,
 template_product_parameter_id bigint NOT NULL REFERENCES template_product_parameters(id) ON DELETE RESTRICT,
 source_type mapping_source NOT NULL,
 checklist_item_id bigint REFERENCES template_checklist_items(id) ON DELETE RESTRICT,
 mapping_rule jsonb NOT NULL DEFAULT '{"operator":"direct"}'::jsonb CHECK (jsonb_typeof(mapping_rule)='object'),
 priority integer NOT NULL DEFAULT 100,
 CHECK ((source_type='question' AND checklist_item_id IS NULL) OR (source_type='checklist_item' AND checklist_item_id IS NOT NULL)),
 UNIQUE (id, template_product_question_id)
);
CREATE TABLE template_report_fields (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 template_product_id bigint NOT NULL REFERENCES template_products(id) ON DELETE RESTRICT,
 field_key text NOT NULL, field_label text NOT NULL,
 rule_json jsonb NOT NULL CHECK (jsonb_typeof(rule_json)='object'),
 sort_order integer NOT NULL DEFAULT 0,
 UNIQUE (template_product_id,field_key)
);

CREATE TABLE surveys (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 survey_no text NOT NULL UNIQUE,
 customer_ref text, surveyed_at timestamptz,
 status survey_status NOT NULL DEFAULT 'draft',
 created_by text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE survey_items (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 survey_id uuid NOT NULL REFERENCES surveys(id) ON DELETE RESTRICT,
 template_product_id bigint NOT NULL REFERENCES template_products(id) ON DELETE RESTRICT,
 item_no integer NOT NULL CHECK (item_no > 0),
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE (survey_id,item_no), UNIQUE (id,template_product_id)
);
CREATE TABLE survey_answers (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 survey_item_id uuid NOT NULL REFERENCES survey_items(id) ON DELETE RESTRICT,
 template_product_question_id bigint NOT NULL REFERENCES template_product_questions(id) ON DELETE RESTRICT,
 answer_json jsonb, -- scalar answer, multi select array, or structured answer
 note_text text,
 answered_by text, answered_at timestamptz,
 UNIQUE (survey_item_id,template_product_question_id),
 UNIQUE (id,template_product_question_id)
);
CREATE TABLE survey_checklist_answers (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 survey_answer_id uuid NOT NULL REFERENCES survey_answers(id) ON DELETE RESTRICT,
 template_checklist_item_id bigint NOT NULL REFERENCES template_checklist_items(id) ON DELETE RESTRICT,
 condition_value jsonb,
 is_visible boolean, -- NULL = not inspected; NOT UI visibility
 note_text text,
 answered_at timestamptz,
 UNIQUE (survey_answer_id,template_checklist_item_id)
);
CREATE TABLE survey_photos (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 survey_answer_id uuid NOT NULL REFERENCES survey_answers(id) ON DELETE RESTRICT,
 survey_checklist_answer_id uuid REFERENCES survey_checklist_answers(id) ON DELETE RESTRICT,
 scope photo_scope NOT NULL,
 storage_key text NOT NULL, original_filename text NOT NULL,
 mime_type text NOT NULL, file_size_bytes bigint NOT NULL CHECK (file_size_bytes>0),
 caption text, sort_order integer NOT NULL DEFAULT 0,
 sha256 text, uploaded_by text NOT NULL, uploaded_at timestamptz NOT NULL DEFAULT now(),
 deleted_at timestamptz,
 CHECK ((scope='question' AND survey_checklist_answer_id IS NULL) OR (scope='checklist_item' AND survey_checklist_answer_id IS NOT NULL))
);
CREATE TABLE survey_parameter_values (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 survey_item_id uuid NOT NULL REFERENCES survey_items(id) ON DELETE RESTRICT,
 template_product_parameter_id bigint NOT NULL REFERENCES template_product_parameters(id) ON DELETE RESTRICT,
 template_mapping_id bigint REFERENCES template_parameter_mappings(id) ON DELETE RESTRICT,
 source_answer_id uuid REFERENCES survey_answers(id) ON DELETE RESTRICT,
 source_checklist_answer_id uuid REFERENCES survey_checklist_answers(id) ON DELETE RESTRICT,
 value_json jsonb NOT NULL,
 unit_snapshot text, rule_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
 calculated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE (survey_item_id,template_product_parameter_id)
);
CREATE TABLE survey_answer_revisions (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 survey_answer_id uuid NOT NULL REFERENCES survey_answers(id) ON DELETE RESTRICT,
 previous_answer_json jsonb, new_answer_json jsonb,
 changed_by text NOT NULL, changed_at timestamptz NOT NULL DEFAULT now(), reason text
);
CREATE TABLE survey_report_snapshots (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 survey_id uuid NOT NULL REFERENCES surveys(id) ON DELETE RESTRICT,
 revision_no integer NOT NULL CHECK (revision_no>0),
 report_payload jsonb NOT NULL CHECK (jsonb_typeof(report_payload)='object'),
 report_file_storage_key text,
 generated_by text NOT NULL, generated_at timestamptz NOT NULL DEFAULT now(),
 finalized_at timestamptz,
 UNIQUE (survey_id,revision_no)
);

-- Cross-parent validation: physical FK alone does not guarantee same template, product or answer parent.
CREATE FUNCTION validate_survey_links() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v1 bigint; v2 bigint; qid bigint; a_id uuid;
BEGIN
 IF TG_TABLE_NAME='template_product_questions' THEN
  SELECT version_id INTO v1 FROM template_products WHERE id=NEW.template_product_id;
  SELECT version_id INTO v2 FROM template_questions WHERE id=NEW.template_question_id;
  IF v1 IS DISTINCT FROM v2 THEN RAISE EXCEPTION 'Question and product version mismatch'; END IF;
 ELSIF TG_TABLE_NAME='template_parameter_mappings' THEN
  SELECT template_product_id,template_question_id INTO v1,qid FROM template_product_questions WHERE id=NEW.template_product_question_id;
  SELECT template_product_id INTO v2 FROM template_product_parameters WHERE id=NEW.template_product_parameter_id;
  IF v1 IS DISTINCT FROM v2 THEN RAISE EXCEPTION 'Parameter mapping product mismatch'; END IF;
  IF NEW.checklist_item_id IS NOT NULL AND (SELECT template_question_id FROM template_checklist_items WHERE id=NEW.checklist_item_id) IS DISTINCT FROM qid THEN
   RAISE EXCEPTION 'Checklist mapping question mismatch';
  END IF;
 ELSIF TG_TABLE_NAME='survey_answers' THEN
  SELECT template_product_id INTO v1 FROM survey_items WHERE id=NEW.survey_item_id;
  SELECT template_product_id INTO v2 FROM template_product_questions WHERE id=NEW.template_product_question_id;
  IF v1 IS DISTINCT FROM v2 THEN RAISE EXCEPTION 'Answer product mismatch'; END IF;
 ELSIF TG_TABLE_NAME='survey_checklist_answers' THEN
  SELECT template_question_id INTO v1 FROM template_product_questions WHERE id=(SELECT template_product_question_id FROM survey_answers WHERE id=NEW.survey_answer_id);
  SELECT template_question_id INTO v2 FROM template_checklist_items WHERE id=NEW.template_checklist_item_id;
  IF v1 IS DISTINCT FROM v2 THEN RAISE EXCEPTION 'Checklist answer question mismatch'; END IF;
 ELSIF TG_TABLE_NAME='survey_photos' THEN
  IF NEW.survey_checklist_answer_id IS NOT NULL THEN
   SELECT survey_answer_id INTO a_id FROM survey_checklist_answers WHERE id=NEW.survey_checklist_answer_id;
   IF a_id IS DISTINCT FROM NEW.survey_answer_id THEN RAISE EXCEPTION 'Photo target mismatch'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='survey_parameter_values' THEN
  SELECT template_product_id INTO v1 FROM survey_items WHERE id=NEW.survey_item_id;
  SELECT template_product_id INTO v2 FROM template_product_parameters WHERE id=NEW.template_product_parameter_id;
  IF v1 IS DISTINCT FROM v2 THEN RAISE EXCEPTION 'Parameter value product mismatch'; END IF;
  IF NEW.source_answer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM survey_answers WHERE id=NEW.source_answer_id AND survey_item_id=NEW.survey_item_id) THEN
   RAISE EXCEPTION 'Parameter source answer mismatch'; END IF;
  IF NEW.source_checklist_answer_id IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM survey_checklist_answers c JOIN survey_answers a ON a.id=c.survey_answer_id
   WHERE c.id=NEW.source_checklist_answer_id AND a.survey_item_id=NEW.survey_item_id
  ) THEN RAISE EXCEPTION 'Parameter source checklist mismatch'; END IF;
  IF NEW.template_mapping_id IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM template_parameter_mappings m JOIN template_product_questions pq ON pq.id=m.template_product_question_id
   WHERE m.id=NEW.template_mapping_id AND m.template_product_parameter_id=NEW.template_product_parameter_id AND pq.template_product_id=v1
  ) THEN RAISE EXCEPTION 'Parameter mapping mismatch'; END IF;
 END IF;
 RETURN NEW;
END; $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['template_product_questions','template_parameter_mappings','survey_answers','survey_checklist_answers','survey_photos','survey_parameter_values'] LOOP
  EXECUTE format('CREATE TRIGGER trg_validate_links BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION validate_survey_links()',t);
 END LOOP;
END $$;

CREATE FUNCTION assert_draft_template() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE version_id_value bigint; state template_status;
BEGIN
 CASE TG_TABLE_NAME
 WHEN 'template_products','template_questions' THEN
  version_id_value := CASE WHEN TG_OP='DELETE' THEN OLD.version_id ELSE NEW.version_id END;
 WHEN 'template_product_questions','template_product_parameters','template_report_fields' THEN
  SELECT version_id INTO version_id_value FROM template_products WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.template_product_id ELSE NEW.template_product_id END;
 WHEN 'template_question_options','template_checklist_items' THEN
  SELECT version_id INTO version_id_value FROM template_questions WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.template_question_id ELSE NEW.template_question_id END;
 WHEN 'template_parameter_mappings' THEN
  SELECT tp.version_id INTO version_id_value FROM template_product_questions pq JOIN template_products tp ON tp.id=pq.template_product_id
  WHERE pq.id=CASE WHEN TG_OP='DELETE' THEN OLD.template_product_question_id ELSE NEW.template_product_question_id END;
 END CASE;
 SELECT status INTO state FROM survey_template_versions WHERE id=version_id_value FOR UPDATE;
 IF state IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Published/retired template is immutable'; END IF;
 -- Also guard the OLD parent of a reparenting UPDATE.
 IF TG_OP='UPDATE' THEN
  CASE TG_TABLE_NAME
  WHEN 'template_products','template_questions' THEN version_id_value := OLD.version_id;
  WHEN 'template_product_questions','template_product_parameters','template_report_fields' THEN
   SELECT version_id INTO version_id_value FROM template_products WHERE id=OLD.template_product_id;
  WHEN 'template_question_options','template_checklist_items' THEN
   SELECT version_id INTO version_id_value FROM template_questions WHERE id=OLD.template_question_id;
  WHEN 'template_parameter_mappings' THEN
   SELECT tp.version_id INTO version_id_value FROM template_product_questions pq JOIN template_products tp ON tp.id=pq.template_product_id
   WHERE pq.id=OLD.template_product_question_id;
  END CASE;
  SELECT status INTO state FROM survey_template_versions WHERE id=version_id_value FOR UPDATE;
  IF state IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Cannot move or change a published/retired template record'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END; $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['template_products','template_questions','template_product_questions','template_product_parameters','template_question_options','template_checklist_items','template_parameter_mappings','template_report_fields'] LOOP
  EXECUTE format('CREATE TRIGGER trg_draft_guard BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION assert_draft_template()',t);
 END LOOP;
END $$;

CREATE FUNCTION protect_template_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Version deletion is not allowed'; END IF;
 IF OLD.status <> 'draft' THEN
  IF NEW IS DISTINCT FROM OLD AND NOT (NEW.status='retired' AND OLD.status='published' AND
     NEW.id=OLD.id AND NEW.template_id=OLD.template_id AND NEW.version_no=OLD.version_no AND NEW.published_at=OLD.published_at AND NEW.created_at=OLD.created_at)
  THEN RAISE EXCEPTION 'Published version definition may not change'; END IF;
 END IF;
 IF OLD.status='draft' AND NEW.status='retired' THEN RAISE EXCEPTION 'Draft must be published first'; END IF;
 IF OLD.status='draft' AND NEW.status='published' AND NEW.published_at IS NULL THEN NEW.published_at := now(); END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER trg_protect_version BEFORE UPDATE OR DELETE ON survey_template_versions FOR EACH ROW EXECUTE FUNCTION protect_template_version();

CREATE FUNCTION ensure_published_survey_item() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM template_products tp JOIN survey_template_versions v ON v.id=tp.version_id
                WHERE tp.id=NEW.template_product_id AND v.status IN ('published','retired')) THEN
  RAISE EXCEPTION 'Survey item must reference a published template version';
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER trg_survey_item_published BEFORE INSERT OR UPDATE OF template_product_id ON survey_items FOR EACH ROW EXECUTE FUNCTION ensure_published_survey_item();

CREATE INDEX idx_template_questions_version_sort ON template_questions(version_id,sort_order);
CREATE INDEX idx_template_checklist_items_question_sort ON template_checklist_items(template_question_id,sort_order);
CREATE INDEX idx_template_mappings_target ON template_parameter_mappings(template_product_parameter_id,priority);
CREATE INDEX idx_survey_items_survey ON survey_items(survey_id);
CREATE INDEX idx_survey_answers_item ON survey_answers(survey_item_id);
CREATE INDEX idx_survey_photos_answer ON survey_photos(survey_answer_id) WHERE deleted_at IS NULL;
CREATE INDEX idx_survey_checklist_answers_answer ON survey_checklist_answers(survey_answer_id);
CREATE INDEX idx_survey_parameter_values_item ON survey_parameter_values(survey_item_id);
CREATE INDEX idx_report_snapshots_survey ON survey_report_snapshots(survey_id);
COMMIT;


-- ---------------------------------------------------------
-- Source-fidelity additions: preserve all source records.
-- Original HTML, PDF and XLSX are stored byte-for-byte in source_assets.
-- ---------------------------------------------------------
BEGIN;
SET search_path TO survey_engine, public;
CREATE TABLE IF NOT EXISTS source_assets (
 asset_key text PRIMARY KEY, filename text NOT NULL, mime_type text NOT NULL,
 sha256 text NOT NULL, original_bytes bytea NOT NULL, imported_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS source_records (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 source_key text NOT NULL REFERENCES source_assets(asset_key) ON DELETE RESTRICT,
 record_type text NOT NULL, record_key text NOT NULL, ordinal integer NOT NULL DEFAULT 0,
 payload jsonb NOT NULL, UNIQUE(source_key,record_type,record_key)
);
CREATE TABLE IF NOT EXISTS source_rules (
 rule_key text PRIMARY KEY, source_expression text NOT NULL,
 note text NOT NULL DEFAULT 'Original JavaScript expression archived; needs port and equivalence tests before runtime evaluation.'
);
CREATE TABLE IF NOT EXISTS survey_preparation_definitions (
 code text PRIMARY KEY, group_name text NOT NULL, label text NOT NULL,
 applies_to jsonb, answer_options jsonb NOT NULL DEFAULT '[]'::jsonb,
 extra_json jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE IF NOT EXISTS survey_field_provenance (
 template_question_id bigint PRIMARY KEY REFERENCES template_questions(id) ON DELETE RESTRICT,
 product_code text NOT NULL, section_key text NOT NULL, field_key text NOT NULL,
 html_definition jsonb NOT NULL,
 source_visibility_expression text,
 source_section_visibility_expression text,
 UNIQUE(product_code,section_key,field_key)
);
CREATE TABLE IF NOT EXISTS survey_reference_data (
 code text PRIMARY KEY, value_json jsonb NOT NULL,
 origin text NOT NULL DEFAULT 'Survey Produk GTE HTML'
);
 SELECT v.id,q.id,s.id,'gte.ejr.ident','Identifikasi','1','EJR.ident.tag','Tag number','text','',true,'','{}'::jsonb,'{"source_rr":null,"input_type_original":null}'::jsonb,'{"enabled":true,"required":false}'::jsonb,'{"enabled":true,"required":false,"max_files":20,"scope":"question","source_behavior":"HTML photo gallery is per product item, not per individual field"}'::jsonb,1001
 FROM survey_template_versions v JOIN survey_templates st ON st.id=v.template_id JOIN questions q ON q.code='gte.tag' JOIN sections s ON s.code='gte.ejr.ident' WHERE st.code='GTE_PRODUCT_SURVEY' AND v.version_no=1 ON CONFLICT(version_id,question_key) DO NOTHING;
 SELECT v.id,q.id,s.id,'gte.ejr.ident','Identifikasi','2','EJR.ident.day','Hari survey','select','',false,'','{}'::jsonb,'{"source_rr":null,"input_type_original":"day"}'::jsonb,'{"enabled":true,"required":false}'::jsonb,'{"enabled":true,"required":false,"max_files":20,"scope":"question","source_behavior":"HTML photo gallery is per product item, not per individual field"}'::jsonb,1002
 FROM survey_template_versions v JOIN survey_templates st ON st.id=v.template_id JOIN questions q ON q.code='gte.day' JOIN sections s ON s.code='gte.ejr.ident' WHERE st.code='GTE_PRODUCT_SURVEY' AND v.version_no=1 ON CONFLICT(version_id,question_key) DO NOTHING;
 SELECT v.id,q.id,s.id,'gte.ejr.ident','Identifikasi','3','EJR.ident.line','Line / sistem / equipment','text','',false,'','{}'::jsonb,'{"source_rr":null,"input_type_original":null}'::jsonb,'{"enabled":true,"required":false}'::jsonb,'{"enabled":true,"required":false,"max_files":20,"scope":"question","source_behavior":"HTML photo gallery is per product item, not per individual field"}'::jsonb,1003
