INSERT INTO source_records(source_key,record_type,record_key,ordinal,payload) VALUES ('pdf','page','1',1,'{"text":"Survey Produk GTE - Form Referensi\nHalaman 1\nSURVEY PRODUK GTE - FORM REFERENSI\nFormat ringkas untuk persiapan dan pelaksanaan survey. Setiap area hanya menampilkan Acuan / Pertanyaan, Opsi Jawaban, dan Keterangan. Informasi wajib, satuan, kondisi tampil, contoh pengisian, serta\ninstruksi penting diringkas di kolom Keterangan.\nAREA: DATA SURVEY\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nNama client / perusahaan\nIsian bebas\nWajib. -\nPlant / area\nIsian bebas\n-\nAlamat lokasi\nIsian bebas\n-\nTanggal mulai\nTanggal\n-\nNama surveyor / tim\nIsian bebas\n-\nPIC client\nIsian bebas\n-\nKontak PIC\nIsian bebas\nContoh: No. HP / email\nNo. inquiry / referensi\nIsian bebas\n-\nTujuan survey\nIsian bebas / keterangan\nContoh: mis. survey shutdown 2027: expansion joint, gasket, dan packing unit 2\n","page":1}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO source_records(source_key,record_type,record_key,ordinal,payload) VALUES ('pdf','page','2',2,'{"text":"Survey Produk GTE - Form Referensi\nHalaman 2\nAREA: PERSIAPAN SURVEY\nScope Produk\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nEJR - Expansion Joint Rubber\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nEJM - Expansion Joint Metal\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nEJF - Expansion Joint Fabric\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nSWG - Spiral Wound Gasket\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nGMG - Grooved Metal Gasket\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nRTI - Removable Thermal Insulation\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nGPP - Gland Packing\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nDFG - Die Formed Graphite\nYa / Tidak\nTentukan apakah produk termasuk scope survey; isi jumlah item bila ada.\nJadwal Survey\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nJadwal survey per hari\nTanggal / Rencana-Area / Produk-Tag /\nStatus / Catatan\nStatus: Rencana / Aktif / Selesai. Form menyediakan beberapa baris untuk penjadwalan.\nDaftar Item yang Disurvey\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nItem / Tag yang akan disurvey\nProduk / Tag Number / Posisi-Lokasi / Hari /\nStatus\nStatus: Belum / Sedang survey / Selesai. Daftarkan seluruh item dari P&ID, line list, inquiry, atau temuan\nlapangan.\nChecklist Peralatan\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nMeteran baja 5–8 m\nSiap / Belum / N/A\nKelompok: Alat ukur umum. Berlaku untuk: Semua produk.\nJangka sorong 150 & 300 mm\nSiap / Belum / N/A\nKelompok: Alat ukur umum. Berlaku untuk: Semua produk.\nPi tape / circumference tape\nSiap / Belum / N/A\nKelompok: Alat ukur umum. Berlaku untuk: Semua produk.\nPenggaris baja 30 cm & 1 m\nSiap / Belum / N/A\nKelompok: Alat ukur umum. Berlaku untuk: Semua produk.\nLaser distance meter\nSiap / Belum / N/A\nKelompok: Alat ukur umum. Berlaku untuk: Semua produk.\nJangka sorong besar 600 mm+\nSiap / Belum / N/A\nKelompok: Alat ukur khusus. Berlaku untuk: EJR, EJM, SWG, GMG.\n","page":2}'::jsonb) ON CONFLICT DO NOTHING;
