INSERT INTO source_records(source_key,record_type,record_key,ordinal,payload) VALUES ('pdf','page','44',44,'{"text":"Survey Produk GTE - Form Referensi\nHalaman 44\nAREA: CATATAN & LAPORAN\nCatatan Lapangan\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nCatatan temuan per hari\nHari / Produk-Item / Waktu / Catatan /\nStatus\nGunakan untuk mencatat temuan aktual selama survey.\nKonfirmasi ke Client\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nPertanyaan / data yang perlu dikonfirmasi\nProduk-Item / PIC Client / Status /\nJawaban-Tindak Lanjut\nStatus: Terbuka / Selesai.\nRingkasan & Rekomendasi\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nRingkasan temuan\nIsian bebas\nRangkum temuan utama.\nRekomendasi awal\nIsian bebas\nTuliskan rekomendasi per produk/item penting.\nData yang perlu dikonfirmasi\nIsian bebas\nJangan mengarang angka yang tidak tersedia; tandai asumsi.\n","page":44}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO source_records(source_key,record_type,record_key,ordinal,payload) VALUES ('pdf','page','45',45,'{"text":"Survey Produk GTE - Form Referensi\nHalaman 45\nAREA: INSTRUKSI UMUM\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nPersiapan - Umum\nTentukan produk yang disurvey, jadwal\nhari, dan daftar item. Checklist alat dan\ndokumen menyesuaikan produk yang\ndipilih.\nBerlaku untuk: Semua.\nPersiapan - Item\nDaftarkan tag dari P&ID, line list, atau\ninquiry. Item bisa ditambah lagi di lapangan.\nBerlaku untuk: Semua.\nDi lapangan - Validasi\nValidasi terhadap acuan yang dipilih, batas\numum material, dan konsistensi data. Tabel\nstandar di aplikasi adalah referensi awal;\nverifikasi ke dokumen standar resmi. Acuan\ncustom dapat ditambahkan untuk\nmembandingkan nilai ukur dengan\ndrawing/spesifikasi client.\nBerlaku untuk: Semua produk pada section Acuan & validasi.\nDi lapangan - Flange\nCocokkan standar dari hasil ukur OD, PCD,\njumlah lubang dan diameter lubang. PCD\njuga dapat dihitung dari jumlah lubang dan\njarak antar pusat lubang bersebelahan.\nBerlaku untuk: Produk dengan koneksi flange.\nDi lapangan - Gap flange\nUkur celah flange di 4 titik: jam 12, 3, 6, dan\n9 serta OD flange. Data dipakai untuk\nmenghitung celah rata-rata dan\nmisalignment angular.\nBerlaku untuk: EJR/EJM/EJF atau produk yang memiliki section pergerakan + flange.\nDi lapangan - Kondisi existing\nCatat kondisi existing/kerusakan yang\nterlihat sesuai checklist khusus produk.\nBerlaku untuk: Semua produk. Checklist failure mode berbeda per produk\nDi lapangan - Foto\nAmbil foto keseluruhan dan detail. Sertakan\nmeteran atau penggaris di dalam foto\nsebagai pembanding ukuran; pilih kategori\nfoto dan beri keterangan.\nBerlaku untuk: Semua produk. Kategori foto tersedia di setiap sheet produk\nDi lapangan - Stuffing box\nHasil hitung stuffing box memakai diameter\nshaft/stem, diameter bore, dan kedalaman\nbox. Untuk GPP, penampang packing =\n(bore - shaft)/2, lalu dibandingkan ke\nukuran standar terdekat.\nBerlaku untuk: GPP dan DFG.\nCatatan - Catatan lapangan\nCatat temuan per hari, simpan pertanyaan\nuntuk client, dan cek kelengkapan serta\nhasil validasi sebelum meninggalkan lokasi.\nBerlaku untuk: Semua.\nCatatan - Konfirmasi client\nSimpan pertanyaan yang masih terbuka\nkepada client dan tandai statusnya setelah\nselesai dikonfirmasi.\nBerlaku untuk: Semua.\n","page":45}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO source_records(source_key,record_type,record_key,ordinal,payload) VALUES ('pdf','page','46',46,'{"text":"Survey Produk GTE - Form Referensi\nHalaman 46\nACUAN / PERTANYAAN\nOPSI JAWABAN\nKETERANGAN\nLaporan - Ringkasan\nTulis ringkasan temuan, rekomendasi awal\nper produk/item penting, data yang perlu\ndikonfirmasi, dan catatan untuk\ndesign/BOM/estimasi.\nBerlaku untuk: Semua. Jangan mengarang angka yang tidak ada; tandai rekomendasi berbasis asumsi.\nLaporan - Review\nPeriksa kembali draf sebelum dikirim,\nterutama rekomendasi material.\nBerlaku untuk: Semua.\n","page":46}'::jsonb) ON CONFLICT DO NOTHING;
