INSERT INTO template_questions(version_id,question_id,section_id,section_code_snapshot,section_label_snapshot,question_no,question_key,label_snapshot,input_type,unit_snapshot,is_required,helper_instruction,visibility_rule,validation_rule,note_config,photo_config,sort_order)
INSERT INTO template_product_questions(template_product_id,template_question_id) SELECT tp.id,tq.id FROM template_products tp JOIN products p ON p.id=tp.product_id JOIN survey_template_versions v ON v.id=tp.version_id JOIN survey_templates st ON st.id=v.template_id JOIN template_questions tq ON tq.version_id=v.id AND tq.question_key='EJR.ident.tag' WHERE p.code='EJR' AND st.code='GTE_PRODUCT_SURVEY' AND v.version_no=1 ON CONFLICT DO NOTHING;
INSERT INTO survey_field_provenance(template_question_id,product_code,section_key,field_key,html_definition,source_visibility_expression,source_section_visibility_expression) SELECT tq.id,'EJR','ident','tag','{"k":"tag","l":"Tag number","crit":1}'::jsonb,NULL,NULL FROM template_questions tq JOIN survey_template_versions v ON v.id=tq.version_id JOIN survey_templates st ON st.id=v.template_id WHERE st.code='GTE_PRODUCT_SURVEY' AND v.version_no=1 AND tq.question_key='EJR.ident.tag' ON CONFLICT DO NOTHING;
INSERT INTO parameters(code,name,data_type,default_unit) VALUES ('gte.tag','Tag number','text','') ON CONFLICT(code) DO NOTHING;
INSERT INTO product_questions(product_id,question_id) SELECT p.id,q.id FROM products p,questions q WHERE p.code='EJR' AND q.code='gte.tag' ON CONFLICT DO NOTHING;
INSERT INTO product_parameters(product_id,parameter_id) SELECT p.id,pa.id FROM products p,parameters pa WHERE p.code='EJR' AND pa.code='gte.tag' ON CONFLICT DO NOTHING;
INSERT INTO question_parameters(question_id,parameter_id) SELECT q.id,pa.id FROM questions q,parameters pa WHERE q.code='gte.tag' AND pa.code='gte.tag' ON CONFLICT DO NOTHING;
INSERT INTO template_product_parameters(template_product_id,parameter_id,parameter_code_snapshot,parameter_name_snapshot,data_type_snapshot,unit_snapshot) SELECT tp.id,pa.id,pa.code,pa.name,pa.data_type,pa.default_unit FROM template_products tp JOIN products p ON p.id=tp.product_id JOIN parameters pa ON pa.code='gte.tag' JOIN survey_template_versions v ON v.id=tp.version_id JOIN survey_templates st ON st.id=v.template_id WHERE p.code='EJR' AND st.code='GTE_PRODUCT_SURVEY' AND v.version_no=1 ON CONFLICT DO NOTHING;
INSERT INTO template_parameter_mappings(template_product_question_id,template_product_parameter_id,source_type,mapping_rule) SELECT pq.id,pp.id,'question','{"operator":"direct","html_key":"tag","source":"HTML form field"}'::jsonb FROM template_product_questions pq JOIN template_questions tq ON tq.id=pq.template_question_id JOIN template_products tp ON tp.id=pq.template_product_id JOIN products p ON p.id=tp.product_id JOIN template_product_parameters pp ON pp.template_product_id=tp.id WHERE p.code='EJR' AND tq.question_key='EJR.ident.tag' AND pp.parameter_code_snapshot='gte.tag' AND NOT EXISTS(SELECT 1 FROM template_parameter_mappings m WHERE m.template_product_question_id=pq.id AND m.template_product_parameter_id=pp.id);
